def solve_one(dose, ts):
    ts = np.asarray(ts, float)
    C = lambda t: pk_conc(dose, t)
    def rhs(t, y): return [ke0*(C(t)-y[0])]
    sol = solve_ivp(rhs, [0, max(ts.max(),1e-6)], [0.0], t_eval=ts, rtol=1e-8, atol=1e-10)
    Ce = sol.y[0]
    return E0*(1 - Emax*Ce/(EC50+Ce))
def predict(df, p):
    global E0, Emax, EC50, ke0
    E0,Emax,EC50,ke0 = p['E0'],p['Emax'],p['EC50'],p['ke0']
    return per_dose(df, solve_one)

